<script setup lang="ts">
import {computed} from 'vue'
import {Clock3,RefreshCw,CheckCircle2,AlertTriangle,LoaderCircle,Copy,Link2} from 'lucide-vue-next'
import {date,notify,type Row} from '../lib'
const props=defineProps<{events:Row[];links?:Row[];status?:string}>()
const rounds=computed(()=>Math.max(1,...props.events.map(e=>Number(e.round)||1),...(props.links||[]).map(e=>Number(e.round)||1)))
const statusLabel:Record<string,string>={running:'开始',completed:'完成',failed:'失败',review:'待核实',waiting:'等待'}
const diagnosticLabels:Record<string,string>={dns_ms:'域名解析',connect_ms:'建立连接',tls_ms:'安全握手',first_byte_ms:'等待首字节',connection_ready_ms:'通道就绪',request_write_ms:'请求发送',response_wait_ms:'响应等待',network_stage_elapsed_ms:'网络阶段耗时',request_attempt:'请求尝试次数',network_stage:'网络阶段',protocol_code:'流程诊断码',network_reason:'网络原因',provider_code:'上游错误码',decline_code:'拒付分类',response_kind:'响应类型'}
const diagnosticValues:Record<string,string>={timeout:'超时',proxy_connect:'代理隧道连接失败',tls:'安全握手失败',dns:'域名解析失败',connection:'建立连接',request_write:'发送请求',response_headers:'等待响应头',response_body:'读取响应内容',json:'JSON',html:'HTML 页面',empty:'空响应',other:'其他格式'}
const diagnosticText=(key:string,value:unknown)=>key.endsWith('_ms')?`${value} 毫秒`:diagnosticValues[String(value)]||String(value)
const duration=(v:unknown)=>Number(v)>=1000?`${(Number(v)/1000).toFixed(1)} 秒`:`${Number(v)||0} 毫秒`
async function copyLink(value:string){
 try{
  if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value)
  else{
   const field=document.createElement('textarea');field.value=value;field.style.cssText='position:fixed;opacity:0;left:0;top:0';field.setAttribute('readonly','');document.body.appendChild(field)
   try{field.select();if(!document.execCommand('copy'))throw new Error('clipboard')}finally{field.remove()}
  }
  notify('结账链接已复制')
 }catch{notify('复制未完成，请选中链接后手动复制')}
}
</script>
<template><section class="payment-trace" aria-label="完整支付链条"><div class="trace-heading"><div><span class="eyebrow">PAYMENT ACTIVITY</span><h3>完整支付链条</h3></div><span class="trace-rounds"><RefreshCw :size="14"/>共 {{rounds}} 轮 · 重建 {{rounds-1}} 次</span></div><p class="trace-hint">时间线自动更新；记录各阶段结果和耗时，敏感凭据与上游请求不在页面中展示。</p><section class="trace-links" aria-label="生成的结账链接"><div class="trace-link-heading"><h4><Link2 :size="16"/>生成的结账链接</h4><small>仅管理员可见</small></div><p class="trace-hint">保留各轮实际生成的链接，仅供排查；历史链接不代表仍可付款。</p><p v-if="!links?.length" class="trace-empty">暂无保留的结账链接。尚未生成或此前已清理的链接无法显示。</p><article v-for="link in links" :key="link.round" class="trace-link-item"><div class="trace-link-heading"><b>第 {{link.round}} 轮</b><button v-if="link.available" type="button" class="text-btn" @click="copyLink(link.url)"><Copy :size="14"/>复制链接</button></div><time>{{link.generated_at?'生成时间：'+date(link.generated_at):'历史保留链接 · 生成时间未记录'}}</time><textarea v-if="link.available" readonly class="trace-link-url mono" :aria-label="'第 '+link.round+' 轮结账链接'" :value="link.url" rows="3" spellcheck="false"/><p v-else class="trace-empty">此轮链接暂无法读取。</p></article></section><p v-if="!events.length" class="trace-empty">此订单尚无新版阶段记录，可查看下方已有业务记录。历史步骤不会补写为已执行。</p><ol v-else><li v-for="(e,i) in events" :key="i" :class="e.state"><span class="trace-icon"><AlertTriangle v-if="['failed','review'].includes(e.state)" :size="16"/><LoaderCircle v-else-if="e.state==='running'" :size="16"/><Clock3 v-else-if="e.state==='waiting'" :size="16"/><CheckCircle2 v-else :size="16"/></span><div class="trace-content"><div class="trace-title"><b>{{e.label}}</b><span class="trace-state">{{statusLabel[e.state]||e.state}}</span><small>第 {{e.round}} 轮</small><small v-if="e.state!=='running'&&Number(e.elapsed_ms)>0">{{duration(e.elapsed_ms)}}</small></div><p v-if="e.http_status||e.request_id" class="mono">{{e.http_status?'响应 '+e.http_status:''}} {{e.request_id?' · 关联编号 '+e.request_id:''}}</p><p v-if="e.description">{{e.description}}</p><dl v-if="e.diagnostics&&Object.keys(e.diagnostics).length" class="trace-diagnostics"><template v-for="(value,key) in e.diagnostics" :key="key"><dt>{{diagnosticLabels[String(key)]||key}}</dt><dd>{{diagnosticText(String(key),value)}}</dd></template></dl><time>{{date(e.created_at)}}</time></div></li></ol></section></template>
<style scoped>
.payment-trace{margin:22px 0;padding:22px;background:#f7f9fc;border:1px solid #e3e9f0;border-radius:14px}.trace-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.trace-heading h3{margin:6px 0}.trace-rounds{display:flex;align-items:center;gap:6px;color:#53647b;font-size:12px;white-space:nowrap}.trace-hint,.trace-empty{color:#77849a;font-size:12px;line-height:1.7}.payment-trace ol{list-style:none;margin:20px 0 0;padding:0}.payment-trace li{display:flex;gap:12px;position:relative;padding:0 0 18px}.payment-trace li:not(:last-child):before{content:'';position:absolute;left:12px;top:25px;bottom:0;width:1px;background:#dbe4ee}.trace-icon{width:26px;height:26px;display:grid;place-items:center;border-radius:50%;background:#e5edf8;color:#496c9a;flex-shrink:0}.completed .trace-icon{background:#e1f3e9;color:#268757}.failed .trace-icon,.review .trace-icon{background:#fff0dd;color:#b87014}.trace-title{display:flex;align-items:center;gap:9px;flex-wrap:wrap;font-size:13px}.trace-title small,.trace-content time{font-size:11px;color:#7c899c}.trace-content p{margin:7px 0;color:#65738b;font-size:12px;line-height:1.7}.trace-state{font-size:11px;color:#526880;background:#e8edf3;padding:2px 7px;border-radius:4px}.failed .trace-state,.review .trace-state{color:#a36215;background:#fff0dd}.trace-content time{display:block;margin-top:5px}@media(max-width:650px){.payment-trace{padding:15px}.trace-heading{align-items:flex-start;flex-direction:column}}
.trace-links{margin-top:18px;padding:16px;background:white;border:1px solid #dce5ed;border-radius:10px}.trace-link-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.trace-link-heading h4{display:flex;align-items:center;gap:7px;font-size:13px;margin:0}.trace-link-heading small,.trace-link-item time{font-size:11px;color:#7c899c}.trace-link-item{padding:13px 0 0}.trace-link-item+.trace-link-item{margin-top:13px;border-top:1px solid #e8edf3}.trace-link-item b{font-size:12px}.trace-link-item time{display:block;margin:7px 0}.trace-link-url{display:block;box-sizing:border-box;width:100%;min-width:0;max-width:100%;font-size:11px;line-height:1.7;resize:vertical;overflow-wrap:anywhere;background:#f7f9fc;color:#53647b;border:1px solid #e3e9f0;border-radius:7px;padding:10px}.trace-link-heading button{display:flex;align-items:center;gap:5px;white-space:nowrap}
.trace-diagnostics{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;margin:8px 0;font-size:11px;color:#65738b}.trace-diagnostics dd{margin:0;overflow-wrap:anywhere}
</style>
